@using Umbraco.Bench.Umbraco.Models;
@using Umbraco.Extensions
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Name;
    var posts = (Model.Children<BlogPost>() ?? Enumerable.Empty<BlogPost>()).OrderByDescending(p => p.PublishDate);
}

<h1 class="text-4xl font-bold mb-4">@Model.Name</h1>
@if (!string.IsNullOrWhiteSpace(Model.Intro))
{
    <p class="text-lg text-slate-600 mb-8">@Model.Intro</p>
}

<div class="mb-12">
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</div>

<h2 class="text-2xl font-semibold mb-6">Posts</h2>
<div class="space-y-10">
    @foreach (var post in posts)
    {
        <article class="border-b border-slate-200 pb-8">
            <a href="@post.Url()" class="block group">
                @if (post.FeaturedImage is not null)
                {
                    <img src="@post.FeaturedImage.GetCropUrl(width: 1200, height: 500)" alt="@post.Name" class="w-full rounded-lg mb-4" loading="lazy" />
                }
                <h3 class="text-2xl font-semibold group-hover:underline">@post.Name</h3>
            </a>
            <p class="text-sm text-slate-500 mt-1">@post.PublishDate.ToString("MMMM d, yyyy")</p>
            <p class="mt-3 text-slate-700">@post.Excerpt</p>
            <a href="@post.Url()" class="inline-block mt-3 text-sm font-medium text-blue-700 hover:underline">Read more &rarr;</a>
        </article>
    }
</div>

